    lastResponse = aiResponse;

    var parsed = TryParseSuggestion<TSuggestion>(
        workItemType,
        aiResponse,
        summary,
        out var suggestion,
        out var error);

    if (parsed && suggestion is not null)
        return suggestion;

    lastError = error;

    prompt = BuildRepairPrompt(
        workItemType,
        summary,
        aiResponse,
        error ?? "The response was invalid.");
}

